#include "driver_ragdoll.hpp"
#include <btBulletDynamicsCommon.h>
#include <regex>
#include <stdexcept>
namespace ofo {namespace {
btVector3 bv(Vec p){return{p.x,p.y,p.z};}btTransform bt(const Mat&m){btTransform t;t.setFromOpenGLMatrix(m.data());return t;}
Vec triple(const std::string&s,const char*name){std::smatch m;std::regex re(std::string(name)+R"(\s*=\s*\{\s*([-0-9.]+)\s*,\s*([-0-9.]+)\s*,\s*([-0-9.]+))");if(!std::regex_search(s,m,re))return{};return{std::stof(m[1]),std::stof(m[2]),std::stof(m[3])};}
std::array<float,2>limits(const std::string&s,const char*name){std::smatch m;std::regex re(std::string(name)+R"(\s*=\s*\{\s*([-0-9.]+)\s*,\s*([-0-9.]+))");if(!std::regex_search(s,m,re))return{};constexpr float rad=3.14159265358979323846f/180;return{std::stof(m[1])*rad,std::stof(m[2])*rad};}
}
std::vector<DriverJointDefinition>native_driver_joints(const NativeDriver&d){std::vector<DriverJointDefinition>out;std::regex re(R"(ParentId\s*=\s*SEGMENT_([A-Z_]+),[\s\S]*?ChildId\s*=\s*SEGMENT_([A-Z_]+),([\s\S]*?MaxForce\s*=\s*\{[^}]*\}))");auto index=[&](std::string n){n=lower(n);for(size_t i=0;i<11;i++)if(d.segments[i].name==n)return i;throw std::runtime_error("Unknown native driver segment");};for(std::sregex_iterator it(d.native_behavior.begin(),d.native_behavior.end(),re),end;it!=end;++it){DriverJointDefinition j;j.parent=index((*it)[1]);j.child=index((*it)[2]);std::string text=(*it)[3];j.hinge=text.find("HINGE")!=text.npos;j.axis1=triple(text,"Axis1");j.axis2=triple(text,"Axis2");j.limit1=limits(text,"Limit1");j.limit2=limits(text,"Limit2");j.max_force=triple(text,"MaxForce");std::smatch m;if(!std::regex_search(text,m,std::regex(R"(Position\s*=\s*Bones\[Segments\.([a-z_]+)\.BoneIndex\])")))throw std::runtime_error("Missing native driver joint anchor");j.anchor_bone=index(m[1]);out.push_back(j);}if(out.size()!=10)throw std::runtime_error("Native driver requires ten joint definitions");return out;}
struct NativeDriverRagdoll::Impl {btDynamicsWorld&world;std::vector<std::unique_ptr<btBoxShape>>shapes;std::array<btTransform,driver_bone_count>render_frames;std::vector<std::unique_ptr<btRigidBody>>owned;std::vector<btRigidBody*>bodies;std::vector<std::unique_ptr<btTypedConstraint>>joints;Impl(btDynamicsWorld&w):world(w){}~Impl(){for(auto&j:joints)world.removeConstraint(j.get());for(auto&b:owned)world.removeRigidBody(b.get());}};
NativeDriverRagdoll::NativeDriverRagdoll(btDynamicsWorld&world,const NativeDriver&d,const DriverPose&pose,const Mat&car,Vec velocity,Vec angular,float totalMass,std::optional<Vec> velocityReference,btRigidBody*owner):impl_(std::make_unique<Impl>(world)){auto&x=*impl_;float sum=0;for(auto&s:d.segments)sum+=s.mass;if(sum<=0||!std::isfinite(totalMass)||totalMass<1)throw std::runtime_error("Native driver mass missing");auto root=bt(car);auto origin=velocityReference?bv(*velocityReference):root.getOrigin();for(size_t i=0;i<11;i++){auto&s=d.segments[i];// Bullet's swept CCD requires a convex root. Bake the authored segment
 // orientation into the body, then undo it when publishing the skin pose.
 auto shape=std::make_unique<btBoxShape>(bv(s.dimension*.5f));
 shape->setMargin(.012f);
 const auto collision_frame=bt(s.orientation);
 x.render_frames[i]=collision_frame.inverse();float mass=totalMass*s.mass/sum;btVector3 inertia;shape->calculateLocalInertia(mass,inertia);btRigidBody::btRigidBodyConstructionInfo ci(mass,nullptr,shape.get(),inertia);ci.m_friction=.65f;ci.m_restitution=.06f;auto body=std::make_unique<btRigidBody>(ci);auto initial=root*bt(pose.parts[i])*collision_frame;body->setWorldTransform(initial);body->setInterpolationWorldTransform(initial);body->setLinearVelocity(bv(velocity)+bv(angular).cross(initial.getOrigin()-origin));body->setAngularVelocity(bv(angular));body->setDamping(.08f,.25f);body->setCcdMotionThreshold(.07f);body->setCcdSweptSphereRadius(.035f);body->setActivationState(ACTIVE_TAG);if(owner)body->setIgnoreCollisionCheck(owner,true);world.addRigidBody(body.get(),8,1|2|4|8|16);x.bodies.push_back(body.get());x.owned.push_back(std::move(body));x.shapes.push_back(std::move(shape));}
 for(auto&j:native_driver_joints(d)){auto&a=*x.bodies[j.parent];auto&b=*x.bodies[j.child];auto skin=root*bt(pose.skin[j.anchor_bone]);auto pivot=skin*bv(d.segments[j.anchor_bone].joint);auto axis=skin.getBasis()*bv(j.axis1);axis.normalize();auto fa=a.getWorldTransform().inverse(),fb=b.getWorldTransform().inverse();if(j.hinge){auto hinge=std::make_unique<btHingeConstraint>(a,b,fa*pivot,fb*pivot,fa.getBasis()*axis,fb.getBasis()*axis,true);hinge->setLimit(j.limit1[0],j.limit1[1],.9f,.3f,1.f);x.joints.push_back(std::move(hinge));}else{auto y=skin.getBasis()*bv(j.axis2);y-=axis*axis.dot(y);if(y.length2()<1e-6f)y=axis.cross(btVector3(0,0,1));y.normalize();auto z=axis.cross(y).normalized();btMatrix3x3 basis(axis.x(),y.x(),z.x(),axis.y(),y.y(),z.y(),axis.z(),y.z(),z.z());btTransform frame(basis,pivot);auto joint=std::make_unique<btGeneric6DofConstraint>(a,b,fa*frame,fb*frame,true);joint->setLinearLowerLimit(btVector3(0,0,0));joint->setLinearUpperLimit(btVector3(0,0,0));joint->setAngularLowerLimit(btVector3(j.limit1[0],j.limit2[0],-.35f));joint->setAngularUpperLimit(btVector3(j.limit1[1],j.limit2[1],.35f));x.joints.push_back(std::move(joint));}world.addConstraint(x.joints.back().get(),true);}
}
NativeDriverRagdoll::~NativeDriverRagdoll()=default;
std::array<Mat,11>NativeDriverRagdoll::snapshot()const{std::array<Mat,11>out;for(size_t i=0;i<11;i++)(impl_->bodies[i]->getWorldTransform()*impl_->render_frames[i]).getOpenGLMatrix(out[i].data());return out;}
const std::vector<btRigidBody*>&NativeDriverRagdoll::bodies()const{return impl_->bodies;}
void NativeDriverRagdoll::set_velocity(Vec v){for(auto*b:impl_->bodies){b->setLinearVelocity(bv(v));b->activate(true);}}
void NativeDriverRagdoll::apply_impulse(Vec impulse){float mass=0;for(auto*b:impl_->bodies)mass+=1/b->getInvMass();for(auto*b:impl_->bodies){b->applyCentralImpulse(bv(impulse)*(1/b->getInvMass())/mass);b->activate(true);}}
}
